import pty, os, time, select, fcntl, termios, struct, sys
def run_pty(args, rows=24, cols=80, keys_seq=None, wait_after=0.6):
    pid, fd = pty.fork()
    if pid==0:
        os.environ["TERM"]="xterm-256color"
        os.execv("/tmp/executable_orig", ["/tmp/executable_orig"]+args)
        os._exit(127)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0,0))
    out=b""
    def drain(timeout=0.8):
        nonlocal out
        end=time.time()+timeout
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.15)
            if fd in r:
                try: data=os.read(fd, 65536)
                except OSError: break
                if not data: break
                out+=data
                end=time.time()+timeout
    drain(1.0)
    snapshots=[out]
    if keys_seq:
        for k in keys_seq:
            out=b""
            try: os.write(fd, k)
            except: break
            drain(0.8)
            snapshots.append(out)
    # quit
    try: os.write(fd, b"q")
    except: pass
    drain(0.5)
    try:
        wpid,status=os.waitpid(pid, os.WNOHANG)
        print("wait after q", wpid, status, file=sys.stderr)
        if wpid==0:
            os.kill(pid,9); os.waitpid(pid,0)
    except Exception as e: print(e, file=sys.stderr)
    return snapshots

if __name__=="__main__":
    import json
    # copy executable to /tmp/executable_orig if needed? Use ./executable path
PY
cp ./executable /tmp/executable_orig 2>&1 || cp executable /tmp/exec_copy; ls -l /tmp/executable_orig; pwd"}

