def test(close_stdin, extra_flags=[], env_extra={}):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH",10,40,0,0))
    # Use subprocess with stdout=slave, stdin=PIPE, stderr=slave
    env=dict(os.environ); env["TERM"]="xterm-256color"; env.update(env_extra)
    p=subprocess.Popen(["less","-FS"]+extra_flags, stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=env, close_fds=True)
    os.close(slave)
    data=open("/tmp/wide.txt","rb").read()
    p.stdin.write(data); p.stdin.flush()
    if close_stdin: p.stdin.close()
    def drain(t=0.7):
        out=b""; end=time.time()+t
        while time.time()<end:
            r,_,_=select.select([master],[],[],0.12)
            if master in r:
                try: d=os.read(master,65536)
                except: break
                if not d: break
                out+=d; end=time.time()+t
        return out
    snap=drain(1.0)
    print("close",close_stdin,extra_flags,env_extra, len(snap), b'\x1b[m\x1b[7m' in snap, repr(snap[130:170]))
    try: os.write(master,b"q")
    except: pass
    drain(0.3)
    try:
        if not close_stdin: p.stdin.close()
    except: pass
    try: p.wait(timeout=2)
    except: p.kill()
    os.close(master)

