import subprocess
def run(args, inp=None):
    if isinstance(inp,str): inp=inp.encode()
    r=subprocess.run(["./executable"]+args, input=inp, capture_output=True)
    return r.stdout.decode(), r.stderr.decode(), r.returncode
def show(label, args, inp=None):
    out,err,rc=run(args,inp)
    print(f"== {label} rc={rc} ==")
    print(out, end='')
