use crate::error::{AppError, AppResult};
use std::collections::VecDeque;
use std::io::{self, BufReader, Read};

#[derive(Clone, Copy, Debug)]
pub struct Position {
    pub byte: u64,
    pub line: u64,
    pub record: u64,
}

struct Source<R: Read> {
    reader: BufReader<R>,
    queue: VecDeque<u8>,
    eof: bool,
    byte_offset: u64,
    line: u64,
}

impl<R: Read> Source<R> {
    fn new(reader: R) -> Self {
        Self {
            reader: BufReader::with_capacity(8192, reader),
            queue: VecDeque::new(),
            eof: false,
            byte_offset: 0,
            line: 1,
        }
    }

    fn fill_one(&mut self) -> AppResult<bool> {
        if self.eof {
            return Ok(false);
        }
        let mut b = [0u8; 1];
        loop {
            match self.reader.read(&mut b) {
                Ok(0) => {
                    self.eof = true;
                    return Ok(false);
                }
                Ok(_) => {
                    self.queue.push_back(b[0]);
                    return Ok(true);
                }
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => return Err(AppError::Io(e)),
            }
        }
    }

    fn peek_at(&mut self, index: usize) -> AppResult<Option<u8>> {
        while self.queue.len() <= index {
            if !self.fill_one()? {
                break;
            }
        }
        Ok(self.queue.get(index).copied())
    }

    fn peek(&mut self) -> AppResult<Option<u8>> {
        self.peek_at(0)
    }

    fn consume(&mut self) -> AppResult<Option<u8>> {
        let b = match self.queue.pop_front() {
            Some(v) => Some(v),
            None => {
                if self.fill_one()? {
                    self.queue.pop_front()
                } else {
                    None
                }
            }
        };
        if let Some(v) = b {
            self.byte_offset += 1;
            if v == b'\n' {
                self.line += 1;
            }
        }
        Ok(b)
    }
}

pub struct CsvParser<R: Read> {
    source: Source<R>,
    delimiter: u8,
    expected_len: Option<usize>,
    record_index: u64,
    first_record: bool,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum State {
    StartField,
    InField,
    InQuotedField,
    InEscapedQuote,
}

impl<R: Read> CsvParser<R> {
    pub fn new(reader: R, delimiter: u8) -> Self {
        Self {
            source: Source::new(reader),
            delimiter,
            expected_len: None,
            record_index: 0,
            first_record: true,
        }
    }

    fn read_byte_record(&mut self) -> AppResult<Option<(Vec<Vec<u8>>, Position)>> {
        let position = Position {
            byte: self.source.byte_offset,
            line: self.source.line,
            record: self.record_index,
        };

        if self.first_record {
            self.first_record = false;
            // Skip a UTF-8 BOM, but only when it appears at the very
            // beginning of the stream.
            if self.source.peek_at(0)? == Some(0xef)
                && self.source.peek_at(1)? == Some(0xbb)
                && self.source.peek_at(2)? == Some(0xbf)
            {
                let _ = self.source.consume()?;
                let _ = self.source.consume()?;
                let _ = self.source.consume()?;
            }
        }

        if self.source.peek()?.is_none() {
            return Ok(None);
        }

        // Skip blank lines. The position captured above intentionally
        // points at the start of this skipping process (this matches the
        // positions reported in error messages). A line terminator left
        // over from a preceding CR terminator is consumed here as well.
        while let Some(b) = self.source.peek()? {
            if b == b'\n' || b == b'\r' {
                let _ = self.source.consume()?;
            } else {
                break;
            }
        }
        if self.source.peek()?.is_none() {
            return Ok(None);
        }

        let quoting = self.delimiter != b'"';
        let mut fields: Vec<Vec<u8>> = Vec::new();
        let mut field: Vec<u8> = Vec::new();
        let mut state = State::StartField;

        loop {
            match state {
                State::StartField => {
                    let Some(b) = self.source.peek()? else {
                        fields.push(field);
                        break;
                    };
                    if b == self.delimiter {
                        let _ = self.source.consume()?;
                        fields.push(field);
                        field = Vec::new();
                    } else if quoting && b == b'"' {
                        let _ = self.source.consume()?;
                        state = State::InQuotedField;
                    } else if b == b'\n' || b == b'\r' {
                        // A terminator at the start of a field ends the
                        // record with a final empty field.
                        let _ = self.source.consume()?;
                        fields.push(field);
                        break;
                    } else {
                        let _ = self.source.consume()?;
                        field.push(b);
                        state = State::InField;
                    }
                }
                State::InField => {
                    let Some(b) = self.source.peek()? else {
                        fields.push(field);
                        break;
                    };
                    if b == self.delimiter {
                        let _ = self.source.consume()?;
                        fields.push(field);
                        field = Vec::new();
                        state = State::StartField;
                    } else if b == b'\n' || b == b'\r' {
                        let _ = self.source.consume()?;
                        fields.push(field);
                        break;
                    } else {
                        let _ = self.source.consume()?;
                        field.push(b);
                    }
                }
                State::InQuotedField => {
                    let Some(b) = self.source.peek()? else {
                        fields.push(field);
                        break;
                    };
                    if b == b'"' {
                        let _ = self.source.consume()?;
                        state = State::InEscapedQuote;
                    } else {
                        let _ = self.source.consume()?;
                        field.push(b);
                    }
                }
                State::InEscapedQuote => {
                    let Some(b) = self.source.peek()? else {
                        fields.push(field);
                        break;
                    };
                    if quoting && b == b'"' {
                        let _ = self.source.consume()?;
                        field.push(b'"');
                        state = State::InQuotedField;
                    } else if b == self.delimiter {
                        let _ = self.source.consume()?;
                        fields.push(field);
                        field = Vec::new();
                        state = State::StartField;
                    } else if b == b'\n' || b == b'\r' {
                        let _ = self.source.consume()?;
                        fields.push(field);
                        break;
                    } else {
                        // The quote we just saw closed the field; any
                        // following characters belong to a plain field.
                        state = State::InField;
                    }
                }
            }
        }

        self.record_index += 1;
        Ok(Some((fields, position)))
    }

    pub fn read_record(&mut self) -> AppResult<Option<Vec<String>>> {
        let Some((fields, position)) = self.read_byte_record()? else {
            return Ok(None);
        };

        if let Some(expected) = self.expected_len {
            if fields.len() != expected {
                return Err(AppError::Csv(format!(
                    "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                    position.record, position.line, position.byte,
                    fields.len(), expected
                )));
            }
        } else {
            self.expected_len = Some(fields.len());
        }

        let mut record = Vec::with_capacity(fields.len());
        for (index, field) in fields.iter().enumerate() {
            match std::str::from_utf8(field) {
                Ok(s) => record.push(s.to_owned()),
                Err(e) => {
                    return Err(AppError::Csv(format!(
                        "CSV parse error: record {} (line {}, field: {}, byte: {}): invalid utf-8: invalid UTF-8 in field {} near byte index {}",
                        position.record, position.line, index, position.byte,
                        index, e.valid_up_to()
                    )));
                }
            }
        }
        Ok(Some(record))
    }
}
