use super::style::Align;
use crate::width::{display_width, truncate_str};

/// Align a (possibly truncated) cell inside `width` columns.
fn aligned(cell: &str, width: usize, align: Align) -> String {
    let truncated;
    let mut text = cell;
    if display_width(cell) > width {
        truncated = truncate_str(cell, width);
        text = truncated;
    }
    let w = display_width(text);
    let diff = width.saturating_sub(w);
    let (left, right) = match align {
        Align::Left => (0, diff),
        Align::Center => (diff / 2, diff - diff / 2),
        Align::Right => (diff, 0),
    };
    let mut out = String::with_capacity(text.len() + diff);
    for _ in 0..left {
        out.push(' ');
    }
    out.push_str(text);
    for _ in 0..right {
        out.push(' ');
    }
    out
}

/// Build one table row line.
pub fn row_line(
    cells: &[String],
    widths: &[usize],
    align: Align,
    padding: usize,
    indent: usize,
    left_border: &str,
    separator: &str,
    right_border: &str,
) -> String {
        let indent_str = format!("{:>indent$}", "", indent = indent);
    let mut line = String::new();
    line.push_str(&indent_str);
    line.push_str(left_border);
    // The padding string is produced by a formatting call once per row;
    // rows without any cell never need it.
    let pad;
    if cells.is_empty() {
        pad = String::new();
    } else {
                             pad = format!("{:>padding$}", "", padding = padding);
    }
    let rpad = &pad;
    for (i, cell) in cells.iter().enumerate() {
        if i > 0 {
            line.push_str(separator);
        }
        let width = widths.get(i).copied().unwrap_or(0);
        line.push_str(rpad);
        line.push_str(&aligned(cell, width, align));
        line.push_str(rpad);
    }
    line.push_str(right_border);
    line
}
