#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Align {
    Left,
    Center,
    Right,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StyleKind {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

#[derive(Clone, Copy)]
pub struct Style {
    // (left, junction, right, horizontal) for each border line kind.
    pub top: Option<(&'static str, &'static str, &'static str, &'static str)>,
    pub middle: Option<(&'static str, &'static str, &'static str, &'static str)>,
    pub bottom: Option<(&'static str, &'static str, &'static str, &'static str)>,
    pub left: &'static str,
    pub separator: &'static str,
    pub right: &'static str,
    /// Whether border lines are also drawn between body rows.
    pub between_rows: bool,
}

impl StyleKind {
    pub fn style(self) -> Style {
        match self {
            StyleKind::None => Style {
                top: None,
                middle: None,
                bottom: None,
                left: "",
                separator: "",
                right: "",
                between_rows: false,
            },
            StyleKind::Ascii => Style {
                top: Some(("+", "+", "+", "-")),
                middle: Some(("+", "+", "+", "-")),
                bottom: Some(("+", "+", "+", "-")),
                left: "|",
                separator: "|",
                right: "|",
                between_rows: false,
            },
            StyleKind::Ascii2 => Style {
                top: None,
                middle: Some((" ", "+", " ", "-")),
                bottom: None,
                left: " ",
                separator: "|",
                right: " ",
                between_rows: false,
            },
            StyleKind::Sharp => Style {
                top: Some(("┌", "┬", "┐", "─")),
                middle: Some(("├", "┼", "┤", "─")),
                bottom: Some(("└", "┴", "┘", "─")),
                left: "│",
                separator: "│",
                right: "│",
                between_rows: false,
            },
            StyleKind::Rounded => Style {
                top: Some(("╭", "┬", "╮", "─")),
                middle: Some(("├", "┼", "┤", "─")),
                bottom: Some(("╰", "┴", "╯", "─")),
                left: "│",
                separator: "│",
                right: "│",
                between_rows: false,
            },
            StyleKind::Reinforced => Style {
                top: Some(("┏", "┬", "┓", "─")),
                middle: Some(("├", "┼", "┤", "─")),
                bottom: Some(("┗", "┴", "┛", "─")),
                left: "│",
                separator: "│",
                right: "│",
                between_rows: false,
            },
            StyleKind::Markdown => Style {
                top: None,
                middle: Some(("|", "|", "|", "-")),
                bottom: None,
                left: "|",
                separator: "|",
                right: "|",
                between_rows: false,
            },
            StyleKind::Grid => Style {
                top: Some(("┌", "┬", "┐", "─")),
                middle: Some(("├", "┼", "┤", "─")),
                bottom: Some(("└", "┴", "┘", "─")),
                left: "│",
                separator: "│",
                right: "│",
                between_rows: true,
            },
        }
    }
