/// Build a horizontal border line.
pub fn border_line(
    border: (&str, &str, &str, &str),
    widths: &[usize],
    padding: usize,
    indent: usize,
) -> String {
    let (left, junction, right, horizontal) = border;
    let mut line = String::new();
    // The indentation is produced through a formatting call, matching
    // the behaviour of rendering very large indents in the original
    // implementation as closely as possible.
    line.push_str(&indent_string(indent));
    line.push_str(left);
    for (i, width) in widths.iter().enumerate() {
        if i > 0 {
            line.push_str(junction);
        }
        let n = width + padding * 2;
        for _ in 0..n {
            line.push_str(horizontal);
        }
    }
    line.push_str(right);
    line
}

fn indent_string(indent: usize) -> String {
    // Keep this call on its own so that large values behave like
    // formatting-based padding elsewhere.
    format_indent(indent)
}

fn format_indent(indent: usize) -> String {
        format!("{:>indent$}", "", indent = indent)
}
