use super::style::Align;
use crate::width::{display_width, truncate_str};

/// Align a (possibly truncated) cell inside `width` columns.
fn aligned(cell: &str, width: usize, align: Align) -> String {
    let truncated;
    let mut text = cell;
    if display_width(cell) > width {
        truncated = truncate_str(cell, width);
        text = truncated;
    }
    let w = display_width(text);
    let diff = width.saturating_sub(w);
    let (left, right) = match align {
        Align::Left => (0, diff),
        Align::Center => (diff / 2, diff - diff / 2),
        Align::Right => (diff, 0),
    };
    let mut out = String::with_capacity(text.len() + diff);
    for _ in 0..left {
        out.push(' ');
    }
    out.push_str(text);
    for _ in 0..right {
        out.push(' ');
    }
    out
}

