cat > src/app.rs <<'RS'
use crate::csv_parser::CsvParser;
use crate::error::{AppError, AppResult};
use crate::table::row::row_line;
use crate::table::style::{border_line, Align, StyleKind};
use crate::width::display_width;
use std::fs::File;
use std::io::{self, IsTerminal, Read, Write};
use std::path::PathBuf;

pub struct Args {
    pub file: Option<PathBuf>,
    pub no_headers: bool,
    pub number: bool,
    pub tsv: bool,
    pub delimiter: char,
    pub style: StyleKind,
    pub padding: usize,
    pub indent: usize,
    pub sniff: usize,
    pub header_align: Align,
    pub body_align: Align,
    pub disable_pager: bool,
}

fn digits(n: usize) -> usize {
    let mut d = 1;
    let mut v = n;
    while v >= 10 {
        v /= 10;
        d += 1;
    }
    d
}

pub fn run(args: &Args, out: &mut dyn Write) -> AppResult<()> {
    let delimiter_char = if args.tsv { '\t' } else { args.delimiter };
    let delimiter = delimiter_char as u8;

    // Resolve the input source.
    let source: Box<dyn Read> = if let Some(path) = &args.file {
        Box::new(File::open(path)?)
    } else if io::stdin().is_terminal() {
        return Err(AppError::Message(
            "no input file specified (use -h for help)".to_string(),
        ));
    } else {
        Box::new(io::stdin())
    };

    let mut parser = CsvParser::new(source, delimiter);

    let headers: Option<Vec<String>> = if args.no_headers {
        None
    } else {
        match parser.read_record()? {
            Some(rec) => Some(rec),
            None => Some(Vec::new()),
        }
    };

    // Sniff records to determine column widths.
    let mut sniffed: Vec<Vec<String>> = Vec::new();
    if args.sniff == 0 {
        while let Some(rec) = parser.read_record()? {
            sniffed.push(rec);
        }
    } else {
        while sniffed.len() < args.sniff {
            match parser.read_record()? {
                Some(rec) => sniffed.push(rec),
                None => break,
            }
        }
    }
    let sniffed_count = sniffed.len();

    // Compute column widths (without the optional line number column).
    let mut widths: Vec<usize> = Vec::new();
    if let Some(h) = &headers {
        for cell in h {
            widths.push(display_width(cell));
        }
    } else if let Some(first) = sniffed.first() {
        for _ in first {
            widths.push(0);
        }
    }
    for rec in &sniffed {
        if widths.len() < rec.len() {
            widths.resize(rec.len(), 0);
        }
        for (i, cell) in rec.iter().enumerate() {
            let w = display_width(cell);
            if w > widths[i] {
                widths[i] = w;
            }
        }
    }

    // The line number column has room for the numbers of the sniffed
    // rows and for the number of the first row after them.
    let number_width = if args.number {
        let mut w = digits(sniffed_count + 1);
        if headers.is_some() {
            w = w.max(1);
        }
        Some(w)
    } else {
        None
    };

    let style = args.style.style();
    let mut full_widths: Vec<usize> = Vec::new();
    if let Some(nw) = number_width {
        full_widths.push(nw);
    }
    full_widths.extend_from_slice(&widths);

    let mut writer = io::BufWriter::new(out);

    if let Some(top) = style.top {
        writeln!(writer, "{}", border_line(top, &full_widths, args.padding, args.indent))?;
    }

    if let Some(h) = &headers {
        let mut cells: Vec<String> = Vec::new();
        if args.number {
            cells.push("#".to_string());
        }
        cells.extend(h.iter().cloned());
        writeln!(
            writer,
            "{}",
            row_line(
                &cells,
                &full_widths,
                args.header_align,
                args.padding,
                args.indent,
                style.left,
                style.separator,
                style.right,
            )
        )?;
    }

    let mut row_number: usize = 0;
    let mut first_body = true;

    let mut print_row = |writer: &mut io::BufWriter<&mut dyn Write>,
                         rec: &[String],
                         row_number: &mut usize,
                         first_body: &mut bool|
     -> AppResult<()> {
        if *first_body {
            if headers.is_some() {
                if let Some(mid) = style.middle {
                    writeln!(
                        writer,
                        "{}",
                        border_line(mid, &full_widths, args.padding, args.indent)
                    )?;
                }
            }
            *first_body = false;
        } else if style.between_rows {
            if let Some(mid) = style.middle {
                writeln!(
                    writer,
                    "{}",
                    border_line(mid, &full_widths, args.padding, args.indent)
                )?;
            }
        }
        *row_number += 1;
        let mut cells: Vec<String> = Vec::new();
        if args.number {
            cells.push(row_number.to_string());
        }
        cells.extend(rec.iter().cloned());
        writeln!(
            writer,
            "{}",
            row_line(
                &cells,
                &full_widths,
                args.body_align,
                args.padding,
                args.indent,
                style.left,
                style.separator,
                style.right,
            )
        )?;
        Ok(())
    };

    for rec in &sniffed {
        print_row(&mut writer, rec, &mut row_number, &mut first_body)?;
    }

    loop {
        match parser.read_record() {
            Ok(Some(rec)) => {
                print_row(&mut writer, &rec, &mut row_number, &mut first_body)?;
            }
            Ok(None) => break,
            Err(e) => {
                // Flush everything that was printed so far before the
                // caller reports the error.
                let _ = writer.flush();
                return Err(e);
            }
        }
    }

    if let Some(bottom) = style.bottom {
        writeln!(
            writer,
            "{}",
            border_line(bottom, &full_widths, args.padding, args.indent)
        )?;
    }
    writer.flush()?;
    Ok(())
}
RS
