    if let Some(h) = &headers {
        for cell in h {
            widths.push(display_width(cell));
        }
    } else if let Some(first) = sniffed.first() {
        for _ in first {
            widths.push(0);
        }
    }
    for rec in &sniffed {
        if widths.len() < rec.len() {
            widths.resize(rec.len(), 0);
        }
        for (i, cell) in rec.iter().enumerate() {
            let w = display_width(cell);
            if w > widths[i] {
                widths[i] = w;
            }
        }
    }

    // The line number column has room for the numbers of the sniffed
    // rows and for the number of the first row after them.
    let number_width = if args.number {
        let mut w = digits(sniffed_count + 1);
        if headers.is_some() {
            w = w.max(1);
        }
        Some(w)
    } else {
        None
    };

    let style = args.style.style();
    let mut full_widths: Vec<usize> = Vec::new();
    if let Some(nw) = number_width {
        full_widths.push(nw);
    }
    full_widths.extend_from_slice(&widths);

    let mut writer = io::BufWriter::new(out);

    if let Some(top) = style.top {
        writeln!(writer, "{}", border_line(top, &full_widths, args.padding, args.indent))?;
    }

    if let Some(h) = &headers {
        let mut cells: Vec<String> = Vec::new();
        if args.number {
            cells.push("#".to_string());
        }
        cells.extend(h.iter().cloned());
        writeln!(
            writer,
            "{}",
            row_line(
                &cells,
                &full_widths,
                args.header_align,
                args.padding,
                args.indent,
                style.left,
                style.separator,
                style.right,
            )
        )?;
    }

    let mut row_number: usize = 0;
    let mut first_body = true;

    let mut print_row = |writer: &mut io::BufWriter<&mut dyn Write>,
                         rec: &[String],
                         row_number: &mut usize,
                         first_body: &mut bool|
     -> AppResult<()> {
        if *first_body {
            if headers.is_some() {
                if let Some(mid) = style.middle {
                    writeln!(
                        writer,
                        "{}",
                        border_line(mid, &full_widths, args.padding, args.indent)
                    )?;
                }
            }
            *first_body = false;
        } else if style.between_rows {
            if let Some(mid) = style.middle {
                writeln!(
                    writer,
                    "{}",
                    border_line(mid, &full_widths, args.padding, args.indent)
                )?;
            }
        }
        *row_number += 1;
        let mut cells: Vec<String> = Vec::new();
        if args.number {
            cells.push(row_number.to_string());
        }
        cells.extend(rec.iter().cloned());
        writeln!(
            writer,
            "{}",
            row_line(
                &cells,
                &full_widths,
                args.body_align,
                args.padding,
                args.indent,
                style.left,
                style.separator,
                style.right,
            )
        )?;
        Ok(())
    };

    for rec in &sniffed {
        print_row(&mut writer, rec, &mut row_number, &mut first_body)?;
    }

    loop {
        match parser.read_record() {
            Ok(Some(rec)) => {
                print_row(&mut writer, &rec, &mut row_number, &mut first_body)?;
            }
            Ok(None) => break,
            Err(e) => {
                // Flush everything that was printed so far before the
                // caller reports the error.
                let _ = writer.flush();
                return Err(e);
            }
        }
    }

    if let Some(bottom) = style.bottom {
        writeln!(
            writer,
            "{}",
            border_line(bottom, &full_widths, args.padding, args.indent)
        )?;
    }
    writer.flush()?;
    Ok(())
}
