                .help("File to view")
                .value_name("FILE")
                .value_parser(clap::value_parser!(PathBuf))
                .index(1),
        )
        .arg(
            Arg::new("no-headers")
                .short('H')
                .long("no-headers")
                .help("Specify that the input has no header row")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("number")
                .short('n')
                .long("number")
                .help("Prepend a column of line numbers to the table")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("tsv")
                .short('t')
                .long("tsv")
                .help("Use '\\t' as delimiter for tsv")
                .conflicts_with("delimiter")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("delimiter")
                .short('d')
                .long("delimiter")
                .help("Specify the field delimiter")
                .value_name("DELIMITER")
                .default_value(",")
                .value_parser(clap::value_parser!(char)),
        )
        .arg(
            Arg::new("style")
                .short('s')
                .long("style")
                .help("Specify the border style")
                .value_name("STYLE")
                .default_value("sharp")
                .value_parser(
                    PossibleValuesParser::new([
                        "none", "ascii", "ascii2", "sharp", "rounded", "reinforced", "markdown",
                        "grid",
                    ])
                    .ignore_case(true),
                ),
        )
        .arg(
            Arg::new("padding")
                .short('p')
                .long("padding")
                .help("Specify padding for table cell")
                .value_name("PADDING")
                .default_value("1")
                .value_parser(clap::value_parser!(usize)),
        )
        .arg(
            Arg::new("indent")
                .short('i')
                .long("indent")
                .help("Specify global indent for table")
                .value_name("INDENT")
                .default_value("0")
                .value_parser(clap::value_parser!(usize)),
        )
        .arg(
            Arg::new("sniff")
                .long("sniff")
                .help(
                    "Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit",
                )
                .value_name("LIMIT")
                .default_value("1000")
                .value_parser(clap::value_parser!(usize)),
        )
        .arg(
            Arg::new("header-align")
                .long("header-align")
                .help("Specify the alignment of the table header")
                .value_name("HEADER_ALIGN")
                .default_value("center")
                .value_parser(
                    PossibleValuesParser::new(["left", "center", "right"]).ignore_case(true),
                ),
        )
        .arg(
            Arg::new("body-align")
                .long("body-align")
                .help("Specify the alignment of the table body")
                .value_name("BODY_ALIGN")
                .default_value("left")
                .value_parser(
                    PossibleValuesParser::new(["left", "center", "right"]).ignore_case(true),
                ),
        )
        .arg(
            Arg::new("disable-pager")
                .short('P')
                .long("disable-pager")
                .help("Disable pager")
                .action(ArgAction::SetTrue),
        )
}

struct Pager {
    child: Child,
}

impl Pager {
    fn spawn() -> Option<Pager> {
        let child = ProcCommand::new("less")
            .env("LESS", "-SF")
            .stdin(Stdio::piped())
            .spawn()
            .ok()?;
        Some(Pager { child })
    }

    fn wait(mut self) -> ExitStatus {
        // Wait for the pager to finish. If waiting itself fails, report
        // success, the interesting output has already happened.
        match self.child.wait() {
            Ok(s) => s,
            Err(_) => unsafe {
                // Fabricate a successful status is not possible; exit
                // codes are handled by the caller via code() on this
                // status, so this branch is defensive only.
                libc::_exit(0);
            },
        }
    }
}

fn exit_status_code(status: ExitStatus) -> i32 {
    if let Some(code) = status.code() {
        return code;
    }
    // The pager was terminated by a signal. Re-raise the signal against
    // ourselves so that our own termination looks the same.
    #[cfg(unix)]
    {
        use std::os::unix::process::ExitStatusExt;
        if let Some(sig) = status.signal() {
            unsafe {
                libc::signal(sig, libc::SIG_DFL);
                libc::raise(sig);
            }
            return 128 + sig;
        }
    }
    0
}

fn main() {
    let matches = build_cli().get_matches();

    let args = Args {
        file: matches.get_one::<PathBuf>("file").cloned(),
        no_headers: matches.get_flag("no-headers"),
        number: matches.get_flag("number"),
        tsv: matches.get_flag("tsv"),
        delimiter: *matches.get_one::<char>("delimiter").unwrap(),
        style: parse_style(matches.get_one::<String>("style").unwrap()),
        padding: *matches.get_one::<usize>("padding").unwrap(),
        indent: *matches.get_one::<usize>("indent").unwrap(),
        sniff: *matches.get_one::<usize>("sniff").unwrap(),
        header_align: parse_align(matches.get_one::<String>("header-align").unwrap()),
        body_align: parse_align(matches.get_one::<String>("body-align").unwrap()),
        disable_pager: matches.get_flag("disable-pager"),
    };

    let use_pager = !args.disable_pager && io::stdout().is_terminal();
    let mut pager: Option<Pager> = None;
    let mut pager_input: Option<std::process::ChildStdin> = None;

    if use_pager {
        if let Some(mut p) = Pager::spawn() {
            pager_input = p.child.stdin.take();
            pager = Some(p);
        }
    }

    let result = if let Some(mut input) = pager_input {
        let r = app::run(&args, &mut input);
        // Closing the pager's stdin signals end-of-input to it.
        drop(input);
        r
    } else {
        let mut stdout = io::stdout();
        let r = app::run(&args, &mut stdout);
        let _ = stdout.flush();
        r
    };

    if let Some(p) = pager {
        // In pager mode our exit status is the pager's exit status. An
        // application error has already been part of the terminal
        // session; report it before waiting if it is a real error.
        if let Err(e) = &result {
            if !e.is_broken_pipe() {
                eprintln!("csview: {}", e);
            }
        }
        let status = p.wait();
        std::process::exit(exit_status_code(status));
    }

    match result {
        Ok(()) => std::process::exit(0),
        Err(e) => {
            if e.is_broken_pipe() {
                std::process::exit(0);
            }
            eprintln!("csview: {}", e);
            std::process::exit(1);
        }
    }
}
