//! A minimal implementation of the terminal-size interface used by
//! command-line formatting code: report the current terminal size in
//! character cells, if there is one.

/// Terminal width in character cells.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

/// Terminal height in character cells.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

/// Return the size of the terminal attached to standard output,
/// standard error or standard input, in that order, if any of them is
/// a terminal with a known size.
pub fn terminal_size() -> Option<(Width, Height)> {
    terminal_size_of(1)
        .or_else(|| terminal_size_of(2))
        .or_else(|| terminal_size_of(0))
}

fn terminal_size_of(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        let mut winsize: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) == 0 && winsize.ws_col > 0 {
            Some((Width(winsize.ws_col), Height(winsize.ws_row)))
        } else {
            None
        }
    }
}
