use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

/// Display width of a string, treating ambiguous-width characters as
/// wide (as is customary for CJK environments). This is the measure
/// used when sniffing column widths.
pub fn display_width(s: &str) -> usize {
    s.width_cjk()
}

/// Width of a string as used when a cell is actually formatted: here
/// ambiguous-width characters count as one column.
pub fn format_width(s: &str) -> usize {
    s.width()
}

/// Truncate a string to at most `max_width` formatting columns.
/// Grapheme clusters are never split; a cluster that would not fit
/// completely is dropped and truncation stops there. Zero-width
/// clusters may still be included after the nominal limit is reached.
pub fn truncate_str(s: &str, max_width: usize) -> &str {
    if format_width(s) <= max_width {
        return s;
    }
    let mut current = 0usize;
    let mut end = 0usize;
    for (index, grapheme) in s.grapheme_indices(true) {
        let w = grapheme.width();
        if current + w > max_width {
            break;
        }
        current += w;
        end = index + grapheme.len();
    }
    &s[..end]
}
