import pathlib
p=pathlib.Path("src/csv_parser.rs")
t=p.read_text()
start=t.index("struct Source<R: Read> {")
end=t.index("pub struct CsvParser")
new='''struct Source<R: Read> {
    reader: R,
    buffer: Vec<u8>,
    pos: usize,
    eof: bool,
    byte_offset: u64,
    line: u64,
}

impl<R: Read> Source<R> {
    fn new(reader: R) -> Self {
        Self {
            reader,
            buffer: Vec::with_capacity(8192),
            pos: 0,
            eof: false,
            byte_offset: 0,
            line: 1,
        }
    }

    fn ensure(&mut self, index: usize) -> AppResult<bool> {
        while self.buffer.len() <= index && !self.eof {
            if self.pos == self.buffer.len() && self.pos > 0 {
                self.buffer.clear();
                self.pos = 0;
            }
            let mut chunk = [0u8; 8192];
            match self.reader.read(&mut chunk) {
                Ok(0) => self.eof = true,
                Ok(n) => self.buffer.extend_from_slice(&chunk[..n]),
                Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
                Err(e) => return Err(AppError::Io(e)),
            }
        }
        Ok(self.buffer.len() > index)
    }

    fn peek_at(&mut self, index: usize) -> AppResult<Option<u8>> {
        let idx = self.pos + index;
        if self.ensure(idx)? {
            Ok(Some(self.buffer[idx]))
        } else {
            Ok(None)
        }
    }

    fn peek(&mut self) -> AppResult<Option<u8>> {
        self.peek_at(0)
    }

    fn consume(&mut self) -> AppResult<Option<u8>> {
        let b = self.peek()?;
        if let Some(v) = b {
            self.pos += 1;
            self.byte_offset += 1;
            if v == b'\\n' {
                self.line += 1;
            }
        }
        Ok(b)
    }
}

