use super::style::Align;
use crate::width::{format_width, truncate_str};
use std::io::Write;

/// Write one table row to `writer`.
///
/// The row is written incrementally: indentation and the left border
/// are emitted before the individual cells are formatted.
pub fn write_row<W: Write>(
    writer: &mut W,
    cells: &[String],
    widths: &[usize],
    align: Align,
    padding: usize,
    indent: usize,
    left_border: &str,
    separator: &str,
    right_border: &str,
) -> std::io::Result<()> {
    let indent_str =
        format!("{:>indent$}", "", indent = indent);
    write!(writer, "{}", indent_str)?;
    write!(writer, "{}", left_border)?;
    let pad;
    if cells.is_empty() {
        pad = String::new();
    } else {
                         pad = format!("{:>padding$}", "", padding = padding);
    }
    for (i, cell) in cells.iter().enumerate() {
        if i > 0 {
            write!(writer, "{}", separator)?;
        }
        let width = widths.get(i).copied().unwrap_or(0);
        write!(writer, "{}", pad)?;
        write!(writer, "{}", aligned(cell, width, align))?;
        write!(writer, "{}", pad)?;
    }
    write!(writer, "{}", right_border)?;
    writeln!(writer)?;
    Ok(())
}

/// Align a (possibly truncated) cell inside `width` columns.
fn aligned(cell: &str, width: usize, align: Align) -> String {
    let truncated;
    let mut text = cell;
    let mut w = format_width(cell);
    if w > width {
        truncated = truncate_str(cell, width);
        text = truncated;
        w = format_width(text);
    }
    let diff = width.saturating_sub(w);
    let (left, right) = match align {
        Align::Left => (0, diff),
        Align::Center => (diff / 2, diff - diff / 2),
        Align::Right => (diff, 0),
    };
    let mut out = String::with_capacity(text.len() + diff);
    for _ in 0..left {
        out.push(' ');
    }
    out.push_str(text);
    for _ in 0..right {
        out.push(' ');
    }
    out
}

/// Build one table row line as a string. Retained for convenience when
/// a complete line is preferred over incremental output.
pub fn row_line(
    cells: &[String],
    widths: &[usize],
    align: Align,
    padding: usize,
    indent: usize,
    left_border: &str,
    separator: &str,
    right_border: &str,
) -> String {
    let mut buf = Vec::new();
    // Writing to a Vec cannot fail.
    let _ = write_row(
        &mut buf,
        cells,
        widths,
        align,
        padding,
        indent,
        left_border,
        separator,
        right_border,
    );
    let mut s = String::from_utf8(buf).unwrap_or_default();
    if s.ends_with('\n') {
        s.pop();
    }
    s
}
