import subprocess, csv, io, json, sys
ORIG="/workspace/executable"; NEW="/tmp/new/executable"

def make_csv(chars, with_marker=False):
    out=io.StringIO(newline='')
    w=csv.writer(out, delimiter=',', quoting=csv.QUOTE_MINIMAL, lineterminator='\n')
    w.writerow(['']*len(chars))
    w.writerow(chars)
    if with_marker:
        w.writerow(['aaaaaaaa']*len(chars))
    return out.getvalue().encode('utf-8')

def run(exe, data):
    r=subprocess.run([exe,"-P"], input=data, capture_output=True)
    if r.returncode!=0:
        raise RuntimeError((r.returncode,r.stderr[:500],data[:200]))
    return r.stdout.decode('utf-8')

def measure_S(exe, chars):
    out=run(exe, make_csv(chars, False))
    lines=out.split('\n')
    top=lines[0]
    # strip corners
    segs=top[1:-1].split('┬')
    if len(segs)!=len(chars):
        raise RuntimeError(f"S segs {len(segs)} vs {len(chars)} top={top[:200]!r}")
    return [len(s)-2 for s in segs]

def measure_F(exe, chars):
    out=run(exe, make_csv(chars, True))
    lines=out.split('\n')
    # lines: top, header, sep, row1, row2, bottom
    row=lines[3]
    segs=row.split('│')[1:-1]
    if len(segs)!=len(chars):
        raise RuntimeError(f"F segs {len(segs)} vs {len(chars)} row={row[:200]!r}")
    vals=[]
    for s in segs:
        # seg = ' ' + char(1 cp) + fill spaces + ' '
        # Fill = trailing spaces -1 (right pad)
        trailing=len(s)-len(s.rstrip(' '))
        fill=trailing-1
        vals.append(8-fill)
    return vals

def probe(cps, batch=800):
    diffs=[]
    skipped=[]
    for start in range(0,len(cps),batch):
        chunk=cps[start:start+batch]
        chars=[]
