use unicode_segmentation::UnicodeSegmentation;
use unicode_width::UnicodeWidthStr;

/// Characters whose width in the Unicode tables used by the reference
/// behaviour is one column, while the tables used here report two.
/// These are mostly symbols that newer Unicode data classify as wide
/// (trigrams, Yijing hexagrams, Tai Xuan Jing symbols, a few Tangut and
/// Miao characters, and the newest emoji), plus, for the CJK measure,
/// a handful of ambiguous symbols.
fn old_narrow(c: char, cjk: bool) -> bool {
    let cp = c as u32;
    // Ranges that are narrow in both measures.
    if matches!(cp,
        0x2630..=0x2637
        | 0x268a..=0x268f
        | 0x31e4..=0x31e5
        | 0x4dc0..=0x4dff
        | 0x16ff2..=0x16ff6
        | 0x187f8..=0x187ff
        | 0x18cff
        | 0x18d09..=0x18d1e
        | 0x18d80..=0x18df2
        | 0x1d300..=0x1d356
        | 0x1d360..=0x1d376
        | 0x1f6d8
        | 0x1fa89..=0x1fa8a
        | 0x1fa8e..=0x1fa8f
        | 0x1fabe
        | 0x1fac6
        | 0x1fac8
        | 0x1facd
        | 0x1fadc
        | 0x1fadf
        | 0x1fae9..=0x1faea
        | 0x1faef
    ) {
        return true;
    }
    // Additional ambiguous symbols that are only narrow for the
    // CJK-aware measure.
    cjk && matches!(cp,
        0x2150..=0x2152
        | 0x2155..=0x215a
        | 0x24ea
        | 0x2574
        | 0x2616..=0x2617
        | 0x2780..=0x2793
        | 0x1f10b..=0x1f10c
    )
}

fn adjusted(base: usize, s: &str, cjk: bool) -> usize {
    let mut result = base as i64;
    for c in s.chars() {
        if old_narrow(c, cjk) {
            result -= 1;
        }
    }
    result.max(0) as usize
}

/// Display width of a string, treating ambiguous-width characters as
/// wide (as is customary for CJK environments). This is the measure
/// used when sniffing column widths.
pub fn display_width(s: &str) -> usize {
    adjusted(s.width_cjk(), s, true)
}

/// Width of a string as used when a cell is actually formatted: here
/// ambiguous-width characters count as one column.
pub fn format_width(s: &str) -> usize {
    adjusted(s.width(), s, false)
}

/// Truncate a string to at most `max_width` formatting columns.
/// Grapheme clusters are never split; a cluster that would not fit
/// completely is dropped and truncation stops there. Zero-width
/// clusters may still be included after the nominal limit is reached.
pub fn truncate_str(s: &str, max_width: usize) -> &str {
    if format_width(s) <= max_width {
        return s;
    }
    let mut current = 0usize;
    let mut end = 0usize;
    for (index, grapheme) in s.grapheme_indices(true) {
        let w = format_width(grapheme);
        if current + w > max_width {
            break;
        }
        current += w;
        end = index + grapheme.len();
    }
    &s[..end]
}
