/// Grapheme clusters are never split; a cluster that would not fit
/// completely is dropped and truncation stops there. Zero-width
/// clusters may still be included after the nominal limit is reached.
pub fn truncate_str(s: &str, max_width: usize) -> &str {
    if format_width(s) <= max_width {
        return s;
    }
    let mut current = 0usize;
    let mut end = 0usize;
    for (index, grapheme) in s.grapheme_indices(true) {
        let w = format_width(grapheme);
        if current + w > max_width {
            break;
        }
        current += w;
        end = index + grapheme.len();
    }
    &s[..end]
}
